#!/usr/bin/env python3
import sys
import os
import argparse
import threading
import select
import termios
import tty
import json
import re
import shlex
import subprocess

help_text = """
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
"""

default_keymap = {
    'Esc': 'peco.Cancel',
    'C-c': 'peco.Cancel',
    'Enter': 'peco.Finish',
    'C-f': 'peco.ForwardChar',
    'C-a': 'peco.BeginningOfLine',
    'C-b': 'peco.BackwardChar',
    'C-d': 'peco.DeleteForwardChar',
    'C-e': 'peco.EndOfLine',
    'C-k': 'peco.KillEndOfLine',
    'C-u': 'peco.KillBeginningOfLine',
    'BS': 'peco.DeleteBackwardChar',
    'C-8': 'peco.DeleteBackwardChar',
    'C-w': 'peco.DeleteBackwardWord',
    'C-g': 'peco.SelectNone',
    'C-n': 'peco.SelectDown',
    'C-p': 'peco.SelectUp',
    'C-r': 'peco.RotateFilter',
    'C-t': 'peco.ToggleQuery',
    'C-Space': 'peco.ToggleSelectionAndSelectNext',
    'ArrowUp': 'peco.SelectUp',
    'ArrowDown': 'peco.SelectDown',
    'ArrowLeft': 'peco.ScrollPageUp',
    'ArrowRight': 'peco.ScrollPageDown',
    'Pgup': 'peco.ScrollPageUp',
    'Pgdn': 'peco.ScrollPageDown',
    'Tab': 'peco.ToggleSelectionAndSelectNext', # Fallback for some terms
}

filters = ["IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy"]

def fuzzy_match(q, text):
    case_sensitive = not q.islower()
    if not case_sensitive:
        text = text.lower()
        q = q.lower()
    q_idx = 0
    t_idx = 0
    while q_idx < len(q) and t_idx < len(text):
        if q[q_idx] == text[t_idx]:
            q_idx += 1
        t_idx += 1
    return q_idx == len(q)

class TermUI:
    def __init__(self, args):
        self.args = args
        self.lines = []
        self.input_done = False
        self.lines_lock = threading.Lock()

        self.orig_stdout_fd = os.dup(sys.stdout.fileno())

        if args.file:
            try:
                self.input_fd = os.open(args.file, os.O_RDONLY)
            except:
                self.input_fd = -1
                self.input_done = True
        elif not sys.stdin.isatty():
            self.input_fd = os.dup(sys.stdin.fileno())
        else:
            self.input_fd = -1
            self.input_done = True

        try:
            self.tty_fd = os.open("/dev/tty", os.O_RDWR)
        except Exception as e:
            print(f"Error: failed to initialize screen: {e}", file=sys.stderr)
            sys.exit(1)

        os.dup2(self.tty_fd, sys.stdin.fileno())
        os.dup2(self.tty_fd, sys.stdout.fileno())

        self.old_settings = termios.tcgetattr(self.tty_fd)
        tty.setraw(self.tty_fd)

        self.use_alt_screen = not bool(args.height)
        if self.use_alt_screen:
            self.write(b"\x1b[?1049h\x1b[H\x1b[2J")
        else:
            self.write(b"\r\n") # ensure some space

        self.keymap = default_keymap.copy()
        self.load_config()

        self.query = args.query
        self.cursor_pos = len(self.query)
        self.current_filter = args.initial_filter
        if self.current_filter not in filters:
            filters.append(self.current_filter)
        self.filter_idx = filters.index(self.current_filter)

        self.matches = []
        self.matches_orig_idx = []
        self.selected_index = args.initial_index
        self.selections = set()

        self.total_pages = 1
        self.current_page = 1

        self.running = True
        self.exit_code = 0

    def load_config(self):
        paths = []
        if self.args.rcfile:
            paths.append(self.args.rcfile)
        else:
            home = os.path.expanduser("~")
            paths.extend([
                os.path.join(home, ".config", "peco", "config.json"),
                os.path.join(home, ".peco", "config.json")
            ])

        for p in paths:
            if os.path.exists(p):
                try:
                    with open(p, 'r') as f:
                        cfg = json.load(f)
                    if "Keymap" in cfg:
                        for k, v in cfg["Keymap"].items():
                            self.keymap[k] = v
                    if "SelectionPrefix" in cfg and not self.args.selection_prefix:
                        self.args.selection_prefix = cfg["SelectionPrefix"]
                except:
                    pass
                break

    def write(self, data):
        try:
            os.write(self.tty_fd, data)
        except:
            pass

    def cleanup(self):
        if self.use_alt_screen:
            self.write(b"\x1b[?1049l")
        else:
            # clear the lines we drew if not alt screen
            self.write(b"\r\n")
        termios.tcsetattr(self.tty_fd, termios.TCSADRAIN, self.old_settings)
        os.close(self.tty_fd)

    def final_output(self, output_lines):
        if self.args.print_query:
            os.write(self.orig_stdout_fd, (self.query + "\n").encode('utf-8'))

        if self.args.exec_cmd:
            cmd = self.args.exec_cmd
            p = subprocess.Popen(['/bin/sh', '-c', cmd], stdin=subprocess.PIPE)
            out_data = ""
            for line in output_lines:
                out_data += line + ("\0" if self.args.null else "\n")
            p.communicate(input=out_data.encode('utf-8'))
        else:
            for line in output_lines:
                os.write(self.orig_stdout_fd, (line + ("\0" if self.args.null else "\n")).encode('utf-8'))

    def reader_thread(self):
        if self.input_fd == -1:
            return
        sep = b'\0' if self.args.null else b'\n'
        buffer = b''
        while True:
            try:
                chunk = os.read(self.input_fd, 4096)
            except:
                break
            if not chunk:
                break
            buffer += chunk
            while sep in buffer:
                line, buffer = buffer.split(sep, 1)
                with self.lines_lock:
                    self.lines.append(line.decode('utf-8', errors='replace'))
                    if self.args.buffer_size and len(self.lines) > self.args.buffer_size:
                        self.lines.pop(0)
        if buffer:
            with self.lines_lock:
                self.lines.append(buffer.decode('utf-8', errors='replace'))
                if self.args.buffer_size and len(self.lines) > self.args.buffer_size:
                    self.lines.pop(0)
        self.input_done = True
        os.close(self.input_fd)

    def parse_keys(self, b):
        keys = []
        i = 0
        while i < len(b):
            if b[i] == 0x1b:
                if i + 2 < len(b) and b[i+1] == ord('['):
                    if b[i+2] == ord('A'): keys.append('ArrowUp'); i+=3
                    elif b[i+2] == ord('B'): keys.append('ArrowDown'); i+=3
                    elif b[i+2] == ord('C'): keys.append('ArrowRight'); i+=3
                    elif b[i+2] == ord('D'): keys.append('ArrowLeft'); i+=3
                    elif b[i+2] == ord('5') and i+3<len(b) and b[i+3]==ord('~'): keys.append('Pgup'); i+=4
                    elif b[i+2] == ord('6') and i+3<len(b) and b[i+3]==ord('~'): keys.append('Pgdn'); i+=4
                    else: keys.append('Esc'); i+=1
                else:
                    keys.append('Esc'); i+=1
            elif b[i] < 32:
                if b[i] == 0: keys.append('C-Space')
                elif b[i] == 9: keys.append('Tab')
                elif b[i] == 13 or b[i] == 10: keys.append('Enter')
                elif b[i] == 8: keys.append('BS')
                elif b[i] == 27: keys.append('Esc')
                else:
                    char = chr(b[i] + 96)
                    keys.append(f'C-{char}')
                i += 1
            elif b[i] == 127:
                keys.append('BS')
                i += 1
            else:
                length = 1
                if (b[i] & 0xE0) == 0xC0: length = 2
                elif (b[i] & 0xF0) == 0xE0: length = 3
                elif (b[i] & 0xF8) == 0xF0: length = 4
                keys.append(b[i:i+length].decode('utf-8', errors='ignore'))
                i += length
        return keys

    def get_terminal_size(self):
        import fcntl, struct
        try:
            res = fcntl.ioctl(self.tty_fd, termios.TIOCGWINSZ, struct.pack('HHHH', 0, 0, 0, 0))
            rows, cols, _, _ = struct.unpack('HHHH', res)
            if self.args.height:
                if '%' in self.args.height:
                    rows = int(rows * float(self.args.height.strip('%')) / 100.0)
                else:
                    rows = int(self.args.height)
            return rows, cols
        except:
            return 24, 80

    def update_matches(self):
        with self.lines_lock:
            current_lines = list(self.lines)

        if not self.query:
            self.matches = current_lines
            self.matches_orig_idx = list(range(len(current_lines)))
            return

        terms = self.query.split()
        self.matches = []
        self.matches_orig_idx = []

        for idx, line in enumerate(current_lines):
            match = True
            for term in terms:
                negate = False
                if term.startswith('-') and len(term) > 1:
                    negate = True
                    term = term[1:]

                term_match = False
                if self.current_filter == "IgnoreCase":
                    term_match = term.lower() in line.lower()
                elif self.current_filter == "CaseSensitive":
                    term_match = term in line
                elif self.current_filter == "SmartCase":
                    if term.islower():
                        term_match = term.lower() in line.lower()
                    else:
                        term_match = term in line
                elif self.current_filter == "IRegexp":
                    try: term_match = bool(re.search(term, line, re.IGNORECASE))
                    except: term_match = False
                elif self.current_filter == "Regexp":
                    try: term_match = bool(re.search(term, line))
                    except: term_match = False
                elif self.current_filter == "Fuzzy":
                    term_match = fuzzy_match(term, line)

                if negate:
                    term_match = not term_match

                if not term_match:
                    match = False
                    break
            if match:
                self.matches.append(line)
                self.matches_orig_idx.append(idx)

    def draw(self):
        rows, cols = self.get_terminal_size()

        prompt = self.args.prompt + " "
        query_str = self.query
        info_str = f"{self.current_filter} [{len(self.matches)} ({self.current_page}/{self.total_pages})]"

        space = cols - len(prompt) - len(query_str) - len(info_str)
        if space < 1: space = 1

        header_line = prompt + query_str + " "*space + info_str

        avail_rows = rows - 1
        if avail_rows < 1: avail_rows = 1

        self.total_pages = max(1, (len(self.matches) + avail_rows - 1) // avail_rows)
        if len(self.matches) == 0:
            self.current_page = 1
        else:
            self.current_page = (self.selected_index // avail_rows) + 1

        start_idx = (self.current_page - 1) * avail_rows
        end_idx = min(start_idx + avail_rows, len(self.matches))

        out = ""
        if self.use_alt_screen:
            out += "\x1b[H" # just move to top, clearing is done once or by line
        else:
            out += f"\x1b[{rows}A" # move up rows

        def render_item(i):
            line = self.matches[i]
            orig_idx = self.matches_orig_idx[i]

            is_selected = (i == self.selected_index)
            is_saved = orig_idx in self.selections

            prefix = ""
            if self.args.selection_prefix:
                if is_selected:
                    prefix = self.args.selection_prefix
                else:
                    prefix = " " * len(self.args.selection_prefix)

            res = prefix + line

            if is_selected:
                res = "\x1b[45m\x1b[4m" + res + "\x1b[0m"
            elif is_saved:
                res = "\x1b[43m\x1b[30m" + res + "\x1b[0m"

            return res + "\x1b[K\r\n"

        if self.args.layout == "top-down":
            out += header_line + "\x1b[K\r\n"
            for i in range(start_idx, end_idx):
                out += render_item(i)
            for i in range(end_idx - start_idx, avail_rows):
                out += "\x1b[K\r\n"
        elif self.args.layout == "bottom-up":
            for i in range(end_idx - start_idx, avail_rows):
                out += "\x1b[K\r\n"
            for i in range(end_idx - 1, start_idx - 1, -1):
                out += render_item(i)
            out += header_line + "\x1b[K"
        elif self.args.layout == "top-down-query-bottom":
            for i in range(start_idx, end_idx):
                out += render_item(i)
            for i in range(end_idx - start_idx, avail_rows):
                out += "\x1b[K\r\n"
            out += header_line + "\x1b[K"

        self.write(out.encode('utf-8'))

    def run(self):
        t = threading.Thread(target=self.reader_thread)
        t.daemon = True
        t.start()

        while self.running:
            self.update_matches()

            # Select 1 logic
            if self.input_done and self.args.select_1 and len(self.matches) == 1:
                self.selected_index = 0
                self.running = False
                break

            # Exit 0 logic
            if self.input_done and self.args.exit_0 and len(self.matches) == 0:
                self.exit_code = 1
                self.running = False
                break

            # Select all logic
            if self.input_done and self.args.select_all:
                for idx in self.matches_orig_idx:
                    self.selections.add(idx)
                self.running = False
                break

            if self.selected_index >= len(self.matches):
                self.selected_index = max(0, len(self.matches) - 1)

            self.draw()

            r, _, _ = select.select([self.tty_fd], [], [], 0.1)
            if r:
                b = os.read(self.tty_fd, 1024)
                if not b:
                    continue
                keys = self.parse_keys(b)
                for k in keys:
                    self.handle_key(k)

        self.cleanup()

        if self.exit_code == 0:
            out_lines = []
            if self.selections:
                # sorted by original index
                for orig_idx in sorted(list(self.selections)):
                    if orig_idx < len(self.lines):
                        out_lines.append(self.lines[orig_idx])
            else:
                if 0 <= self.selected_index < len(self.matches):
                    out_lines.append(self.matches[self.selected_index])
            self.final_output(out_lines)

        sys.exit(self.exit_code)

    def handle_key(self, k):
        action = self.keymap.get(k)

        # If it's a normal character (length 1 and not in keymap)
        if not action and len(k) == 1 and ord(k) >= 32:
            self.query = self.query[:self.cursor_pos] + k + self.query[self.cursor_pos:]
            self.cursor_pos += 1
            return

        if not action:
            return

        if action == 'peco.Cancel':
            self.running = False
            self.exit_code = 1 if self.args.on_cancel == 'error' else 0
        elif action == 'peco.Finish':
            self.running = False
        elif action == 'peco.ForwardChar':
            self.cursor_pos = min(len(self.query), self.cursor_pos + 1)
        elif action == 'peco.BackwardChar':
            self.cursor_pos = max(0, self.cursor_pos - 1)
        elif action == 'peco.BeginningOfLine':
            self.cursor_pos = 0
        elif action == 'peco.EndOfLine':
            self.cursor_pos = len(self.query)
        elif action == 'peco.DeleteForwardChar':
            self.query = self.query[:self.cursor_pos] + self.query[self.cursor_pos+1:]
        elif action == 'peco.DeleteBackwardChar':
            if self.cursor_pos > 0:
                self.query = self.query[:self.cursor_pos-1] + self.query[self.cursor_pos:]
                self.cursor_pos -= 1
        elif action == 'peco.KillEndOfLine':
            self.query = self.query[:self.cursor_pos]
        elif action == 'peco.KillBeginningOfLine':
            self.query = self.query[self.cursor_pos:]
            self.cursor_pos = 0
        elif action == 'peco.DeleteBackwardWord':
            parts = self.query[:self.cursor_pos].rstrip().rsplit(' ', 1)
            if len(parts) == 1:
                self.query = self.query[self.cursor_pos:]
                self.cursor_pos = 0
            else:
                self.query = parts[0] + ' ' + self.query[self.cursor_pos:]
                self.cursor_pos = len(parts[0]) + 1
        elif action == 'peco.SelectDown':
            self.selected_index = min(len(self.matches) - 1, self.selected_index + 1)
        elif action == 'peco.SelectUp':
            self.selected_index = max(0, self.selected_index - 1)
        elif action == 'peco.ScrollPageDown':
            rows, _ = self.get_terminal_size()
            self.selected_index = min(len(self.matches) - 1, self.selected_index + rows - 1)
        elif action == 'peco.ScrollPageUp':
            rows, _ = self.get_terminal_size()
            self.selected_index = max(0, self.selected_index - (rows - 1))
        elif action == 'peco.RotateFilter':
            self.filter_idx = (self.filter_idx + 1) % len(filters)
            self.current_filter = filters[self.filter_idx]
        elif action == 'peco.ToggleQuery':
            # not trivial without storing last query, skipping
            pass
        elif action == 'peco.SelectNone':
            self.selections.clear()
        elif action == 'peco.ToggleSelection':
            if len(self.matches) > 0:
                orig_idx = self.matches_orig_idx[self.selected_index]
                if orig_idx in self.selections:
                    self.selections.remove(orig_idx)
                else:
                    self.selections.add(orig_idx)
        elif action == 'peco.ToggleSelectionAndSelectNext':
            if len(self.matches) > 0:
                orig_idx = self.matches_orig_idx[self.selected_index]
                if orig_idx in self.selections:
                    self.selections.remove(orig_idx)
                else:
                    self.selections.add(orig_idx)
                self.selected_index = min(len(self.matches) - 1, self.selected_index + 1)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('--query', type=str, default="")
    parser.add_argument('--rcfile', type=str)
    parser.add_argument('--version', action='store_true')
    parser.add_argument('-b', '--buffer-size', type=int)
